export const PROCESS_READING_GUIDES = [
  {id:'understanding-railway-handovers',domain:'processes',title:'Six boundaries hidden inside the word handover',summary:'Learn which subject, evidence and responsibility is changing before drawing a process.',sources:['PR01','PR02','PR03','PR04','PR05','PR06','PR07','D02','OC04','OC05'],sections:[
    {heading:'Start with the subject',text:"Start by asking what is being transferred. A changed component needs an updated configuration record. A completed asset needs a receiving team. Infrastructure work needs handback to operational control. Maintenance needs release information, and a new duty holder needs the current operating picture. Incident coordination connects continuing reports and actions. These six maps distinguish those subjects and show the people, information and decisions involved.",sources:['PR03','OC05']},
    {heading:'Configuration and change',text:"Configuration management keeps the system and its records in agreement. A baseline identifies an agreed version; controlled change records how that version changes. For example, replacing a module with one that has a different connector can affect the interface definition, installation record and test scope. The decision to approve the change comes before implementation. Verification then checks the item actually installed, including any differences from the plan.",sources:['PR01','PR02']},
    {heading:'Asset handover is a lifecycle interface',text:"The receiving team needs more than a finished physical asset. It needs the configuration, test results, operating and maintenance information, support arrangements and a record of outstanding work. ARTC connects these readiness needs with commissioning and handover. Metrolinx distinguishes in-service information, handover records and asset-register updates. Follow the map to see how the recipients identify what they are accepting and how they will maintain its records.",sources:['PR03','PR04']},
    {heading:'Worksite handback concerns a different boundary',text:"Worksite handback connects the actual condition after work with operational control. The work team describes what was completed, what remains and any restrictions. Other disciplines check dependent interfaces: finishing one task may leave another system awaiting work or information. The receiving controller needs to understand the resulting conditions. Handback information, electrical restoration and permission for a train movement have separate responsibilities.",sources:['PR06','PR07']},
    {heading:'Maintenance delivery, fleet readiness and duty continuity',text:"ORR’s maintenance model separates the technical work and release documentation from fleet-maintenance management’s return-to-operation decision. The latter considers the vehicle’s intended use and any restrictions. Duty handover transfers a different subject: the current situation between people. HSE describes preparation, a two-way exchange and cross-checking by the incoming person. In both cases, unresolved issues need an identified owner and a route for follow-up.",sources:['D02','OC04']},
    {heading:'Coordination continues while evidence develops',text:"Incident coordination brings reports and responsible teams together. Operational assessment, passenger support and technical investigation can run in parallel, with each team returning updates to a shared record. Acknowledging an event records attention; resolving it requires evidence about the condition. Follow a component link from the map, then return to see who uses its information and what decision that information supports.",sources:['OC05','OC03']},
  ]},
  {id:'people-automation-and-control',domain:'people',title:'People, automation and train-control families',summary:'Understand what GoA changes without confusing a supplier, a radio or a staffing model with an operating function.',sources:['S08','PR08','PR09','T01','S15','S16','S05','PR10','PR11','OC01'],sections:[
    {heading:'Begin with responsibilities',text:"The role cards describe functions that railways allocate to people. One person may carry several functions, or several teams may share them. Traffic coordination, signalling control, power supervision, passenger support and maintenance use different information and produce different outputs. Read each card’s inputs, responsibilities and outputs together. A service plan describes intended operation; a movement authority gives permission for a defined train movement.",sources:['OC01','O01','D02']},
    {heading:'GoA describes train-operating allocation',text:"Grades of automation describe who performs train-operating tasks. GoA1 uses manual driving. GoA2 automates driving with a driver present. GoA3 uses driverless operation with an onboard operating attendant. GoA4 supports routine operation without either role. These grades describe operating responsibilities, independently of the signalling supplier. Degraded operation and recovery still need defined arrangements.",sources:['S08','PR08']},
    {heading:'Passenger and field responsibilities remain visible',text:"Automated driving still requires passenger communication, assistance, emergency response, maintenance and control-room coordination. ORR’s GoA4 guidance addresses these responsibilities. The Community of Metros research summary records operators choosing to carry attendants for customer service even where the trains could operate unattended. The chosen staffing model therefore depends on passenger needs and operating conditions as well as technical capability.",sources:['PR08','PR09']},
    {heading:'Keep families, functions and suppliers separate',text:"The train-control map introduces conventional signalling, communications-based train control (CBTC) and the European Train Control System (ETCS). Protection, automatic operation, supervision, route control and detection are functions within these arrangements. Automatic train control (ATC) is a broad term whose use varies between sources. ETCS is part of the European Rail Traffic Management System (ERTMS); automatic train operation (ATO) can be added as a separate function. SelTrac, Trainguard MT and Urbalis are supplier product families with their own architectures. Historical SelTrac sources may name Thales; Hitachi Rail acquired that business in May 2024.",sources:['T01','S08','S15','S16','S05','PR10','PR11']},
    {heading:'A device can belong in several explanations',text:"A track circuit or axle counter detects the condition of a track section. A balise or other reference transponder supplies information when a train passes. A radio transports messages. These devices can support different control architectures. Start with a family overview, inspect the device, then return to the functional diagram to see how that system uses its information.",sources:['S13','S14','S16','S18','PR10']},
  ]},
];

